// "Designs" section of the home page from scripts/data/dribbble.json
// (generated by scripts/build-dribbble.mjs). Without shots, the section isn't rendered.

import fs from 'node:fs';

const escapeText = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escapeAttr = (s) => escapeText(s).replace(/"/g, '&quot;');

const START = '<!-- dribbble:start (generated by scripts/build-i18n.mjs from scripts/data/dribbble.json) -->';
const MARKER_RE = /<!-- dribbble:start[\s\S]*?<!-- dribbble:end -->/;

// DISABLED: the links to Dribbble (on each shot and the "See more on
// Dribbble" button) are off because the account isn't Pro yet and the profile
// can't be used yet. The shots are only displayed (no link). To turn them
// back on: replace the <div class="designs__link"> with
// <a class="designs__link" href="${s.url}" target="_blank" rel="noopener">
// and remove the HTML comment around the button.
function designsSection({ profile, shots = [] } = {}) {
  if (!shots.length) return `${START}\n      <!-- dribbble:end -->`;
  const cards = shots
    .map(
      (s) => `          <li class="designs__item">
            <div class="designs__link">
              <img class="designs__img" src="${escapeAttr(s.image)}" alt="" width="${s.width}" height="${s.height}" loading="lazy" decoding="async" />
              <span class="designs__caption">${escapeText(s.title)}</span>
            </div>
          </li>`,
    )
    .join('\n');
  return `${START}
      <section id="designs" tabindex="-1" class="designs section">
        <h2 data-i18n="designsTitle" class="section__title">Designs</h2>
        <p data-i18n="designsDescription" class="designs__description">Designs</p>
        <ul class="designs__grid">
${cards}
        </ul>
        <!-- Disabled: the Dribbble account isn't Pro yet (the profile can't be used yet).
        <a class="btn btn--primary designs__more" href="${escapeAttr(profile)}" target="_blank" rel="noopener">See more on Dribbble</a>
        -->
      </section>
      <!-- dribbble:end -->`;
}

/** Replaces the block between the dribbble:start/end markers in index.html */
export function injectDesigns(html, dataPath) {
  if (!MARKER_RE.test(html)) return html;
  const data = fs.existsSync(dataPath) ? JSON.parse(fs.readFileSync(dataPath, 'utf8')) : {};
  return html.replace(MARKER_RE, () => designsSection(data));
}
